#[local] Abbreviation bregs := (PECRS1S.bregs R0 S fb len).
#[local] Abbreviation finish_rs := (PECRS1S.finish_rs L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation call_fill := (PECRS1S.call_fill L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation call_srd := (PECRS1S.call_srd L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation base_keep := (PECRS1S.base_keep L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation unread_nn := (PECRS1S.unread_nn L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation src_callee_mem := (PECRS1S.src_callee_mem L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation fast := (PECRS2S.fast L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).
#[local] Abbreviation slow := (PECRS2S.slow L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UN0 POK FBS SRDS KONT).

(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma after_fill (fx : FPState) R M model s sm sm1 cr (c : Z) :
  bregs R -> getr R (reg 10) = Z_to_bv 64 c -> 0 <= c <= PM.CHUNK -> 1 <= len ->
  st_ok M model s sm1 cr -> fields_eq s -> PMSP.src_step (PM.p_src s0) (PM.p_src s) sm0 sm ->
  PMSP.src_step (PM.p_src s) (PM.p_src s) sm sm1 -> PM.sr_rem (PM.p_src s) = 0 -> PM.sm_g sm1 = PM.sm_g sm + c ->
  PM.unread (PM.p_src s) sm = PM.unread (PM.p_src s0) sm0 -> 0 <= blen pl - (PM.sm_eg sm - PM.sm_g sm) ->
  L5.bytes_at RSEGS M (PM.sr_qc (PM.p_src s)) (UbjRef.slice pl (blen pl - (PM.sm_eg sm - PM.sm_g sm)) c) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x39874 M model) K.
